/* Russian menu trial: static OFL fonts; original faces retained. */
@font-face { coh-font-sdf: on; font-family: "LMU RU Body"; font-style: normal; font-weight: 400; src: url("/start/fonts/ru/Roboto-Regular.ttf") format("truetype"); }
@font-face { coh-font-sdf: on; font-family: "LMU RU Body"; font-style: normal; font-weight: 600; src: url("/start/fonts/ru/Roboto-SemiBold.ttf") format("truetype"); }
@font-face { coh-font-sdf: on; font-family: "LMU RU Body"; font-style: normal; font-weight: 700; src: url("/start/fonts/ru/Roboto-Bold.ttf") format("truetype"); }
@font-face { coh-font-sdf: on; font-family: "LMU RU Heading"; font-style: normal; font-weight: 600; src: url("/start/fonts/ru/RobotoCondensed-SemiBold.ttf") format("truetype"); }
@font-face { coh-font-sdf: on; font-family: "LMU RU Display"; font-style: normal; font-weight: 900; src: url("/start/fonts/ru/Roboto-Black.ttf") format("truetype"); }

/* Only the English language slot contains the Russian trial. */
html[lang="en"] {
  --ff-body: "LMU RU Body", "Heebo", "BIZ UDPGothic", "Noto Sans SC", "Pretendard JP", sans-serif;
  --ff-heading: "LMU RU Heading", "Antonio", "BIZ UDPGothic", "Noto Sans SC", "Paperlogy", sans-serif;
  --ff-heading-secondary: "LMU RU Display", "Lexend", sans-serif;
}

/* LMU RU 1.1: bounded headers and readable quick settings. */
html[lang="en"] ._track-header_z0j6c_1 > :last-child { flex: 1; min-width: 0; }
html[lang="en"] ._primary-heading-wrapper_z0j6c_26 { min-width: 0; width: 100%; }
html[lang="en"] ._primary-heading-wrapper_z0j6c_26 > :first-child { flex-shrink: 0; }
html[lang="en"] ._track-name-heading_z0j6c_41 { flex: 1; min-width: 0; font-size: 3.5rem; }
html[lang="en"] ._condensed-text-wrapper_1w65i_1 { width: 100%; min-width: 0; overflow: visible; }
html[lang="en"] ._condensed-text_1w65i_1 { display: inline-block; white-space: nowrap; }
html[lang="en"] ._track-location-heading_z0j6c_47 { font-family: "Lexend", "LMU RU Display", sans-serif; font-size: 2.4rem; -webkit-text-stroke-width: 0.045rem; text-stroke-width: 0.045rem; }
html[lang="en"] ._quick-settings_17tkl_1 { gap: 1.2rem; }
html[lang="en"] ._setting-node-wrapper_17tkl_23 { --setting-font-size: 1.3rem; font-size: 1.3rem; }
html[lang="en"] ._car-class-card_4cm5z_1 { min-width: 8rem; }
html[lang="en"] ._car-class-card_4cm5z_1 h3 { font-size: 1.05rem; }
